import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - days);
  return base;
};

const presets = [
  { key: 'today', label: 'Сегодня', days: 0 },
  { key: 'yesterday', label: 'Вчера', days: 1 },
  { key: 'week', label: 'Неделя назад', days: 7 },
];

const isSameDay = (a: Date | null, b: Date) =>
  a !== null &&
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({ defaultValue = null, onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(defaultValue);

  const select = (next: Date | null) => {
    setDate(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.days);
          return (
            <JxChip
              key={preset.key}
              active={isSameDay(date, presetDate)}
              onClick={() => select(presetDate)}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={select} />
    </div>
  );
}

